public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time required to collect all apples at node 0
    int minTime = 0;
    // Create a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];
    // Create a queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();
    // Mark the starting node as visited
    visited[0] = true;
    // Enqueue the starting node
    queue.add(0);

    while (!queue.isEmpty()) {
        // Dequeue a node from the queue
        int node = queue.poll();
        // If the current node has an apple, add 2 to the minimum time
        if (hasApple[node]) {
            minTime += 2;
        }
        // Iterate through the edges of the current node
        for (int[] edge : edges) {
            // If the destination node has not been visited, mark it as visited and enqueue it
            if (!visited[edge[1]]) {
                visited[edge[1]] = true;
                queue.add(edge[1]);
            }
        }
    }

    // If not all nodes have been visited, return -1
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            return -1;
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return minTime;
}

public static String sortString(String s) {
      // Sort the characters in the string and store them in an array
      char[] chars = s.toCharArray();
      Arrays.sort(chars);

      // Loop through the array and build the result string
      String result = "";
      int i = 0;
      while (i < chars.length) {
        // Find the smallest character in the remaining array
        char smallest = chars[i];
        int smallestIndex = i;
        for (int j = i + 1; j < chars.length; j++) {
          if (chars[j] < smallest) {
            smallest = chars[j];
            smallestIndex = j;
          }
        }

        // Find the largest character in the remaining array
        char largest = chars[i];
        int largestIndex = i;
        for (int j = i + 1; j < chars.length; j++) {
          if (chars[j] > largest) {
            largest = chars[j];
            largestIndex = j;
          }
        }

        // Add the smallest character to the result string
        result += smallest;

        // Add the largest character to the result string
        result += largest;

        // Remove the smallest and largest characters from the array
        chars[smallestIndex] = chars[chars.length - 1];
        chars[largestIndex] = chars[chars.length - 1];
        chars = Arrays.copyOf(chars, chars.length - 2);
        i++;
      }

      return result;
    }

